#################################################################################
# Read file and output a not split list
#################################################################################
def read_file(L_file_name):
	done_input1_switch=0 
	while not done_input1_switch: 
		input_file0s=split(L_file_name) 
		input_file1=input_file0s[0] 
		input_file1_exist=os.access(input_file1, os.F_OK) 
		input_file1_read=os.access(input_file1, os.R_OK) 
		if input_file1_exist==0: 
			print(("""\n ERROR: File with  name %s does not exist. 
 Please try again.\n: """ % input_file1)) 
			sys.exit(1) 
		elif input_file1_read==0: 
			print("""\n ERROR: The program can not read the file.\n: """) 
			sys.exit(1)   
		else: 
			done_input1_switch=1    
	file_open=open(L_file_name,'r')
	file_lines = file_open.readlines()
	file_open.close()
	return(file_lines)
#################################################################################

#################################################################################
# Read file and output a split list
#################################################################################
def read_file_split(L_file_name):
	done_input1_switch=0
	file_lines=[] 
	while not done_input1_switch: 
		input_file0s=split(L_file_name) 
		input_file1=input_file0s[0] 
		input_file1_exist=os.access(input_file1, os.F_OK) 
		input_file1_read=os.access(input_file1, os.R_OK) 
		if input_file1_exist==0: 
			print(("""\n ERROR: File with  name %s does not exist. 
 Please try again.\n: """ % input_file1)) 
			sys.exit(1) 
		elif input_file1_read==0: 
			print("""\n ERROR: The program can not read the file.\n: """) 
			sys.exit(1)   
		else: 
			done_input1_switch=1    
	file_open=open(L_file_name,'r')
	nonsplit_file_lines = file_open.readlines()
	file_open.close()
	for line in nonsplit_file_lines:
		line_split=split(line)
		file_lines=file_lines+[line_split]
	return(file_lines)
#################################################################################

#################################################################################
# Function to check if an input file exist
#################################################################################
def check_file(L_file_name):
	done_input1_switch=0 
	while not done_input1_switch: 
		input_file0s=split(L_file_name) 
		input_file1=input_file0s[0] 
		input_file1_exist=os.access(input_file1, os.F_OK) 
		input_file1_read=os.access(input_file1, os.R_OK) 
		if input_file1_exist==0: 
			print(("""\n ERROR: File with  name % does not exist. 
 Please try again.\n: """ % input_file1)) 
			sys.exit(1) 
		elif input_file1_read==0: 
			print("""\n ERROR: The program can not read the file.\n: """) 
			sys.exit(1)   
		else: 
			done_input1_switch=1    
	return(L_file_name)
#################################################################################

#################################################################################
# PyNMR-STAR helpers
#################################################################################
def _normalize_nmrstar_value(value):
	if value in (None, ".", "?", ""):
		return None
	return value


def _loop_tag_map(loop_obj):
	return {tag.split(".")[-1]: index for index, tag in enumerate(loop_obj.get_tag_names())}


def _parse_shifty_header(stripped_line):
	parts=split(stripped_line)
	if (len(parts)<3) or (parts[0]!=SHIFTY_HEADER_PREFIX) or (parts[1]!=SHIFTY_HEADER_SECOND_COLUMN):
		return(None)
	column_index={}
	for index,column_name in enumerate(parts):
		column_index[column_name]=index
	return(column_index)


def _is_shifty_header_line(stripped_line):
	return(_parse_shifty_header(stripped_line) is not None)


def _is_shifty_sequence_line(stripped_line):
	parts=split(stripped_line)
	return((len(parts)>=3) and (parts[0]=="#SEQ"))


def _parse_optional_shifty_float(parts,column_index,column_name):
	index=column_index.get(column_name)
	if (index is None) or (index>=len(parts)):
		return(None)
	try:
		return(float(parts[index]))
	except ValueError:
		return(None)


def _normalize_entity_id(value):
	normalized_value=_normalize_nmrstar_value(value)
	if normalized_value is None:
		return(None)
	return(str(normalized_value))


def _entity_sort_key(entity_id):
	try:
		return(0,int(float(entity_id)))
	except ValueError:
		return(1,entity_id)


def _select_entity_id(sequences_by_entity,requested_entity_id):
	if requested_entity_id is not None:
		if requested_entity_id not in sequences_by_entity:
			print(("""\n ERROR: Entity %s was not found in the NMR-STAR input.\n: """ % requested_entity_id))
			sys.exit(1)
		return(requested_entity_id)
	if len(sequences_by_entity)==0:
		print("""\n ERROR: No usable entity sequences were found in the NMR-STAR file.\n: """)
		sys.exit(1)
	return(sorted(sequences_by_entity.keys(),key=_entity_sort_key)[0])


def _looks_like_shifty_row(stripped_line):
	parts=split(stripped_line)
	if len(parts)<8:
		return(0)
	try:
		int(parts[0])
	except ValueError:
		return(0)
	if (parts[1] in ["A","C","D","E","F","G","H","I","K","L","M","N","P","Q","R","S","T","V","W","Y"]) or (parts[1] in aa_names_full_all_CAP):
		return(1)
	return(0)


def _shifty_residue_to_three_letter(token):
	token=token.upper()
	for three_letter_name in aa_names_full_all_CAP:
		if aa_names_full_all_CAP[three_letter_name]==token:
			return(three_letter_name)
	if token in aa_names_full_all_CAP:
		return(token)
	return(None)


def _canonical_supported_atom_name(residue_name, atom_name):
	upper_atom=atom_name.upper()
	if (upper_atom=="H") or (upper_atom=="HN") or (upper_atom=="NH"):
		return("H")
	if upper_atom=="HA":
		return("HA")
	if (residue_name=="GLY") and ((upper_atom=="HA2") or (upper_atom=="HA3")):
		return("HA")
	if (upper_atom=="C") or (upper_atom=="CO"):
		return("C")
	if upper_atom=="CA":
		return("CA")
	if upper_atom=="CB":
		return("CB")
	if upper_atom=="N":
		return("N")
	return(None)


def canonicalize_supported_shift_rows(l_atom_shift_rows):
	grouped_shift_rows={}
	for shift_row in l_atom_shift_rows:
		residue_number=shift_row[0]
		residue_name=shift_row[1]
		atom_id=shift_row[2]
		bmrb_shift=shift_row[3]
		canonical_atom_name=_canonical_supported_atom_name(residue_name,atom_id)
		if canonical_atom_name is None:
			continue
		group_key=(residue_number,residue_name,canonical_atom_name)
		if group_key not in grouped_shift_rows:
			grouped_shift_rows[group_key]=[]
		grouped_shift_rows[group_key]=grouped_shift_rows[group_key]+[bmrb_shift]
	canonical_rows=[]
	for group_key in grouped_shift_rows:
		residue_number,residue_name,canonical_atom_name=group_key
		shift_values=grouped_shift_rows[group_key]
		average_shift=MLab.mean(shift_values)
		canonical_rows=canonical_rows+[[residue_number,residue_name,canonical_atom_name,average_shift]]
	canonical_rows.sort(key=lambda item: (item[0],SUPPORTED_ATOM_ORDER.get(item[2],99),item[2]))
	return(canonical_rows)


def detect_input_format(L_file_name):
	input_file1=check_file(L_file_name)
	file_open=open(input_file1,'r')
	try:
		for line in file_open:
			stripped_line=line.strip()
			if stripped_line=="":
				continue
			if _is_shifty_header_line(stripped_line):
				return("SHIFTY")
			if _looks_like_shifty_row(stripped_line):
				return("SHIFTY")
			return("NMRSTAR")
	finally:
		file_open.close()
	return("NMRSTAR")


def read_nmrstar_entry(L_file_name):
	input_file1=check_file(L_file_name)
	if pynmrstar is None:
		print("""\n ERROR: The pynmrstar package is required to read NMR-STAR files.\n: """)
		sys.exit(1)
	return pynmrstar.Entry.from_file(input_file1)


def read_nmrstar_atom_chem_shifts(l_bmrb_entry,l_selected_entity_id=None):
	atom_shift_rows=[]
	sequences_by_entity={}
	for loop_obj in l_bmrb_entry.get_loops_by_category("_Entity_poly_seq"):
		tag_map=_loop_tag_map(loop_obj)
		residue_tag=None
		for candidate_tag in ["Comp_index_ID","Num","Seq_ID"]:
			if candidate_tag in tag_map:
				residue_tag=candidate_tag
				break
		if (residue_tag is None) or ("Mon_ID" not in tag_map):
			continue
		entity_id_tag="Entity_ID" if "Entity_ID" in tag_map else None
		for row in loop_obj.data:
			residue_number=_normalize_nmrstar_value(row[tag_map[residue_tag]])
			residue_name=_normalize_nmrstar_value(row[tag_map["Mon_ID"]])
			if (residue_number is None) or (residue_name is None):
				continue
			row_entity_id=_normalize_entity_id(row[tag_map[entity_id_tag]]) if entity_id_tag is not None else "1"
			if row_entity_id is None:
				row_entity_id="1"
			if row_entity_id not in sequences_by_entity:
				sequences_by_entity[row_entity_id]={}
			sequences_by_entity[row_entity_id][int(float(residue_number))]=residue_name
	selected_entity_id_local=_select_entity_id(sequences_by_entity,l_selected_entity_id)
	loop_list=l_bmrb_entry.get_loops_by_category("_Atom_chem_shift")
	if len(loop_list)==0:
		print("""\n ERROR: No _Atom_chem_shift loop was found in the NMR-STAR file.\n: """)
		sys.exit(1)
	for loop_obj in loop_list:
		tag_map=_loop_tag_map(loop_obj)
		required_tags=["Comp_index_ID","Comp_ID","Atom_ID","Val"]
		missing_required_tag=0
		for tag in required_tags:
			if tag not in tag_map:
				missing_required_tag=1
				break
		if missing_required_tag==1:
			continue
		entity_id_tag="Entity_ID" if "Entity_ID" in tag_map else None
		for row in loop_obj.data:
			row_entity_id=_normalize_entity_id(row[tag_map[entity_id_tag]]) if entity_id_tag is not None else "1"
			if row_entity_id is None:
				row_entity_id="1"
			if row_entity_id!=selected_entity_id_local:
				continue
			residue_number=_normalize_nmrstar_value(row[tag_map["Comp_index_ID"]])
			residue_name=_normalize_nmrstar_value(row[tag_map["Comp_ID"]])
			atom_id=_normalize_nmrstar_value(row[tag_map["Atom_ID"]])
			bmrb_shift=_normalize_nmrstar_value(row[tag_map["Val"]])
			if (residue_number is None) or (residue_name is None) or (atom_id is None) or (bmrb_shift is None):
				continue
			try:
				residue_number=int(float(residue_number))
				bmrb_shift=float(bmrb_shift)
			except ValueError:
				continue
			atom_shift_rows=atom_shift_rows+[[residue_number,residue_name,atom_id,bmrb_shift]]
	if len(atom_shift_rows)==0:
		print("""\n ERROR: No usable atom chemical shift rows were found in the NMR-STAR file.\n: """)
		sys.exit(1)
	return(canonicalize_supported_shift_rows(atom_shift_rows))


def read_b_cys_from_nmrstar(l_atom_shift_rows):
	B_Cys=[]
	for shift_row in l_atom_shift_rows:
		residue_number=shift_row[0]
		residue_name_full=shift_row[1]
		atom_id=shift_row[2]
		bmrb_shift=shift_row[3]
		residue_name=aa_names_full_all_CAP[residue_name_full]
		b_atom_type=atom_id[0:2]
		if (b_atom_type=="CB") and (residue_name=="C") and (bmrb_shift>35.0):
			B_Cys=B_Cys+[residue_number]
	return(B_Cys)


def bmrb_to_aa_legacy(l_bmrb_lines):
	aa_start_trigger1="_Residue_label"
	aa_stop_trigger1="_Atom_name"
	aa_stop_trigger2="stop_"
	start_flag=0
	aa_res_name_num_dic={}
	for line in l_bmrb_lines:
		split_line=split(line)
		if len(split_line)>0:
			if split_line[0]==aa_start_trigger1:
				start_flag=1
			if (split_line[0]==aa_stop_trigger1) or (split_line[0]==aa_stop_trigger2):
				start_flag=0
			elif (len(split_line)>1) and (start_flag==1) and (split_line[0]!=aa_start_trigger1):
				res_number_found=0
				res_name_found=0
				for entry in split_line:
					if res_number_found==0:
						res_num=entry
						res_number_found=1
						res_name_found=0
					elif (res_number_found==1) and (res_name_found==0) and (len(entry)==3):
						try:
							float(entry)
						except ValueError:
							try:
								res_num_int=int(float(res_num))
							except ValueError:
								break
							aa_res_name_num_dic[res_num_int]=entry
							res_name_found=1
							res_number_found=0
	if len(aa_res_name_num_dic)==0:
		return([])
	aa_res_name_num_list=[]
	for res_num_int in sorted(aa_res_name_num_dic):
		aa_res_name_num_list=aa_res_name_num_list+[[aa_res_name_num_dic[res_num_int],str(res_num_int)]]
	return(aa_res_name_num_list)


def read_legacy_nmrstar_atom_chem_shifts(l_bmrb_lines):
	atom_shift_rows=[]
	start_flag=0
	for line in l_bmrb_lines:
		split_line=split(line)
		if len(split_line)>0:
			if split_line[0]==trigger1:
				start_flag=1
				continue
			if split_line[0]==trigger2:
				start_flag=0
				continue
			if (len(split_line)>3) and (start_flag==1):
				try:
					residue_name=split_line[2]
					atom_id=split_line[3]
					bmrb_shift=float(split_line[5])
				except Exception:
					try:
						residue_name=split_line[3]
						atom_id=split_line[4]
						bmrb_shift=float(split_line[6])
					except Exception:
						continue
				try:
					residue_number=int(split_line[1])
				except ValueError:
					continue
				if residue_name in aa_names_full_all_CAP:
					atom_shift_rows=atom_shift_rows+[[residue_number,residue_name,atom_id,bmrb_shift]]
	return(canonicalize_supported_shift_rows(atom_shift_rows))


def read_legacy_nmrstar_data(L_file_name):
	bmrb_lines=read_file(L_file_name)
	aa_res_name_num_list=bmrb_to_aa_legacy(bmrb_lines)
	atom_shift_rows=read_legacy_nmrstar_atom_chem_shifts(bmrb_lines)
	if (len(aa_res_name_num_list)==0) and (len(atom_shift_rows)>0):
		aa_res_name_num_dic={}
		for residue_number,residue_name,atom_id,bmrb_shift in atom_shift_rows:
			aa_res_name_num_dic[residue_number]=residue_name
		for residue_number in sorted(aa_res_name_num_dic):
			aa_res_name_num_list=aa_res_name_num_list+[[aa_res_name_num_dic[residue_number],str(residue_number)]]
	return(aa_res_name_num_list,atom_shift_rows)


def read_shifty_data(L_file_name):
	input_file1=check_file(L_file_name)
	file_open=open(input_file1,'r')
	file_lines=file_open.readlines()
	file_open.close()
	aa_names_one_to_three={}
	for three_letter_name in aa_names_full_all_CAP:
		aa_names_one_to_three[aa_names_full_all_CAP[three_letter_name]]=three_letter_name
	aa_res_name_num_dic={}
	atom_shift_rows=[]
	header_found=0
	column_index=None
	for line in file_lines:
		stripped_line=line.strip()
		if stripped_line=="":
			continue
		if _is_shifty_header_line(stripped_line):
			header_found=1
			column_index=_parse_shifty_header(stripped_line)
			continue
		if _is_shifty_sequence_line(stripped_line):
			split_line=split(stripped_line)
			if len(split_line)>=3:
				try:
					residue_number=int(split_line[1])
				except ValueError:
					continue
				residue_name_value=split_line[2]
				if residue_name_value in aa_names_one_to_three:
					aa_res_name_num_dic[residue_number]=aa_names_one_to_three[residue_name_value]
				elif residue_name_value in aa_names_full_all_CAP:
					aa_res_name_num_dic[residue_number]=residue_name_value
			continue
		if stripped_line.startswith("#"):
			continue
		if (column_index is None) and (_looks_like_shifty_row(stripped_line)==1):
			header_found=1
			column_index={}
			for column_name in SHIFTY_LEGACY_COLUMN_INDEX:
				column_index[column_name]=SHIFTY_LEGACY_COLUMN_INDEX[column_name]
		split_line=split(stripped_line)
		if column_index is None:
			continue
		residue_number=int(split_line[0])
		residue_name_three_letter=_shifty_residue_to_three_letter(split_line[1])
		if residue_name_three_letter is None:
			continue
		aa_res_name_num_dic[residue_number]=residue_name_three_letter
		ha_value=_parse_optional_shifty_float(split_line,column_index,"HA")
		if (ha_value is not None) and (ha_value!=0.0):
			atom_shift_rows=atom_shift_rows+[[residue_number,residue_name_three_letter,"HA",ha_value]]
		for column_name, atom_name in [("HN","H"),("CO","C"),("CA","CA"),("CB","CB"),("N","N")]:
			shift_value=_parse_optional_shifty_float(split_line,column_index,column_name)
			if (shift_value is None) or (shift_value==0.0):
				continue
			atom_shift_rows=atom_shift_rows+[[residue_number,residue_name_three_letter,atom_name,shift_value]]
	if (header_found==0) or (len(aa_res_name_num_dic)==0):
		print("""\n ERROR: No usable SHIFTY data were found in the input file.\n: """)
		sys.exit(1)
	aa_res_name_num_list=[]
	for residue_number in sorted(aa_res_name_num_dic):
		aa_res_name_num_list=aa_res_name_num_list+[[aa_res_name_num_dic[residue_number],str(residue_number)]]
	return(aa_res_name_num_list,canonicalize_supported_shift_rows(atom_shift_rows))


def read_input_sequence_and_shifts(L_file_name,l_selected_entity_id=None):
	input_format=detect_input_format(L_file_name)
	if input_format=="SHIFTY":
		aa_res_name_num_list, atom_shift_rows=read_shifty_data(L_file_name)
		return(input_format,None,aa_res_name_num_list,atom_shift_rows)
	try:
		bmrb_entry=read_nmrstar_entry(L_file_name)
		atom_shift_rows=read_nmrstar_atom_chem_shifts(bmrb_entry,l_selected_entity_id)
		aa_res_name_num_list=bmrb_to_aa(bmrb_entry,l_selected_entity_id)
		return(input_format,bmrb_entry,aa_res_name_num_list,atom_shift_rows)
	except Exception as exc:
		aa_res_name_num_list, atom_shift_rows=read_legacy_nmrstar_data(L_file_name)
		if (len(aa_res_name_num_list)>0) and (len(atom_shift_rows)>0):
			return("NMRSTAR21",None,aa_res_name_num_list,atom_shift_rows)
		print(("\n ERROR: Unable to parse NMR-STAR file %s with pynmrstar.\n%s\n" % (L_file_name, exc)))
		sys.exit(1)
