# Function to make a directory
###############################################################################
def make_dir(dir_name):
	dir_exist=os.access(dir_name, os.F_OK)
	if dir_exist==0:
		os.system('mkdir %s' %  dir_name)
	else: 
		os.system('rm -r -f %s' %  dir_name)	
		os.system('mkdir %s' %  dir_name)
	return()	
