######################################################################################
# Function to delete a defined number of data points from the start and the end of the list of combined Dynamr and MD results
#####################################################################################
def data_delete(l_list_to_clean,l_points_to_delete):
	l_list_length=len(l_list_to_clean)
	New_list=[]
	N_term_count=1
	for i in range(0,l_list_length):
		l_cell=l_list_to_clean[i]		
		if 	N_term_count>l_points_to_delete:
			New_list=New_list+[l_cell]
		else:
			#if len(l_cell[2])>0:	
			#	N_term_count=N_term_count+1
			N_term_count=N_term_count+1
	New_list.reverse()
	New_list_length=len(New_list)
	New_list2=[]
	C_term_count=1
	for i in range(0,New_list_length):
		l_cell=New_list[i]		
		if 	C_term_count>l_points_to_delete:
			New_list2=New_list2+[l_cell]
		else:
			#if len(l_cell[2])>0:	
			#	C_term_count=C_term_count+1
			C_term_count=C_term_count+1
	New_list2.reverse()
	return(New_list2)
#####################################################	
def data_delete2(l_list_to_clean,l_first_res,l_last_res):
	l_list_length=len(l_list_to_clean)
	New_list=[]
	N_term_count=1
	for i in range(0,l_list_length):
		l_cell=l_list_to_clean[i]
		l_resid_num=int(l_cell[0])
		if (l_resid_num!=int(l_first_res)) and (l_resid_num!=int(l_last_res)):
			New_list=New_list+[l_cell]	
	return(New_list)
#####################################################

#####################################################	
def data_delete3(l_list_to_clean,l_first_res,l_last_res):
	l_list_length=len(l_list_to_clean)
	New_list=[]
	N_term_count=1
	for i in range(0,l_list_length):
		l_cell=l_list_to_clean[i]
		l_resid_num=int(l_cell[0])
		if (l_resid_num!=int(l_first_res)) and (l_resid_num!=int(l_last_res)) and (l_resid_num!=int(l_first_res)+1) and (l_resid_num!=int(l_last_res)-1):
			New_list=New_list+[l_cell]	
	return(New_list)
