######################################################################
# Function to create a list with secondary structure elements from a GromPy string
#########################################################################
def secstr_to_list(l_secstr,l_offset):
	l_end_flag=0
	l_start_flag=0
	result_list=[]
	l_start=""
	l_end=""
	found=0		
	for item in l_secstr:
		if item=="r":
			l_start_flag=1
			l_end_flag=0
			if found==1:
				l_list=list(range(int(l_start),int(l_end)+1))
				result_list=result_list+l_list
				l_start=""
				l_end=""
				found=0													
		if item=="-":
			l_end_flag=1			
			l_start_flag=0		
	
		if (l_start_flag==1) and (item!="_") and (item!="-") and (item!="r"):
			l_start=l_start+item
			l_end_flag=0
		if (l_end_flag==1) and (item!="_") and (item!="-") and (item!="r"):
			l_end=l_end+item
			l_start_flag=0
			found=1			

	l_list=list(range(int(l_start),int(l_end)+1))
	result_list=result_list+l_list
	result_list1=[]
	for i in result_list:
		j=i+l_offset
		result_list1=result_list1+[j]	
	return(result_list1)
