def rci_only(m_list_of_files,m_md_result,m_best_ten_coef_corr_true,m_number_of_best_matches,l_coeff_list):
	compare_list_true=[]
	compare_list_abs=[]
	dynamr_to_md_adjust=[]
	for filename in m_list_of_files:
		compare_list_corr_true=[]
		comparison_true=[]
		comparison_abs=[]
		correlation_true_MD=[]
		correlation_true_Dynamr=[]
		md_data=[]
		dynamr_data=[]
		md_data_ave=[]
		dynamr_data_ave=[]
		dynamr_to_md_ratio=1		
		for entry in m_md_result:
			residue_number=entry[0]
			residue_name=entry[1]
			if len(entry[2])>0:
				for cell in entry[2]:				
					file_name=cell[0]
					m_atoms_real=cell[1]					
					m_data_type=cell[2]
					m_smooth_type=cell[3]													
					if file_name==filename:				
						dynamr_value=cell[-1]
						MD_value=cell[-2] 
						comparison_true=comparison_true+[[dynamr_value, MD_value]]
						correlation_true_Dynamr=correlation_true_Dynamr+[dynamr_value]
						correlation_true_MD=correlation_true_MD+[MD_value]
						md_data=md_data+[[residue_number,residue_name,MD_value]]
						dynamr_data=dynamr_data+[[residue_number,residue_name, dynamr_value]]
						if int(residue_number) in secstr_list:
							md_data_ave=md_data_ave+[MD_value]
							dynamr_data_ave=dynamr_data_ave+[abs(dynamr_value)]

		dynamr_to_md_ratio="NONE"
		dynamr_to_md_ratio=0
		entry_found_true_corr=0
		counter=0
		corel_coef=l_Pearson_coeff=l_Spearman_coeff=0																		
		if (len(correlation_true_Dynamr)>0) and (len(correlation_true_MD)>0):
			compare_list_corr_true=[abs(corel_coef),filename,"correlation",corel_coef,l_coeff_list,md_data,dynamr_data,dynamr_to_md_ratio]

			for item in m_best_ten_coef_corr_true:
				if len(item)>0:
					name_of_file=item[0]										
					if name_of_file==filename:
						if len(item[1])<number_of_best_matches:							
							if 	corel_coef not in m_best_ten_coef_corr_true[counter][5]:
								m_best_ten_coef_corr_true[counter][1]=m_best_ten_coef_corr_true[counter][1]+[compare_list_corr_true]
								m_best_ten_coef_corr_true[counter][5]=m_best_ten_coef_corr_true[counter][5]+[corel_coef]
								m_best_ten_coef_corr_true[counter][1].sort()							
						else:
							m_best_ten_coef_corr_true[counter][1].sort()
							if 	corel_coef not in m_best_ten_coef_corr_true[counter][5]:
								if abs(corel_coef)>m_best_ten_coef_corr_true[counter][1][0][0]:
									m_best_ten_coef_corr_true[counter][1][0]=compare_list_corr_true
									m_best_ten_coef_corr_true[counter][5]=m_best_ten_coef_corr_true[counter][5]+[corel_coef]
									m_best_ten_coef_corr_true[counter][1].sort()

						entry_found_true_corr=1
				counter=counter+1			
			if entry_found_true_corr==0:
				m_best_ten_coef_corr_true=m_best_ten_coef_corr_true+[[filename,[compare_list_corr_true],m_atoms_real,m_data_type,m_smooth_type,[corel_coef]]]
	return(m_best_ten_coef_corr_true,m_list_of_files,l_Pearson_coeff,l_Spearman_coeff)
