			dynamr_to_md_ratio=md_data_mean/dynamr_data_mean
			dynamr_to_md_ratio_out="%s %s %s %s %s %s %s %s %s %s %s %s %s %s" % (dynamr_to_md_ratio,filename,bmrb_file,md_file,nameoffile,corr_suff,end_corr_suff,no_fl_suff,RC_author,preceed_res_effect_name,next_res_effect_name,neighbor_name,smooth,final_smooth) + linesep
			l_file_out_open.write(dynamr_to_md_ratio_out)
