# Function to write GNU plot macros
#########################################################################################
def gnuplot_macro(l_md_data,l_dyna_data,l_filename,l_coef,l_title,l_scale_factor):
	f=os.popen('gnuplot','w')
	print("set data style linespoints", file=f)
	print("set terminal postscript color", file=f)
	print("set terminal postscript solid", file=f)
	print("set title '%s and %s'" % (l_filename,l_title), file=f) 
	print("set ylabel '%s'" % "Chem. shift sum or scaled MD Data", file=f)
	print("set xlabel '%s'" % "Residue number", file=f)
	print("set output '%s.ps'" % l_md_data, file=f)
	print("plot [][]'%s' title 'MD %s (scaled by %s)' with linespoints lt 1 pt 3, '%s' title 'Chem.shift sum (%s)' with linespoints lt 3 pt 6" % (l_md_data,l_filename,l_scale_factor,l_dyna_data,l_coef), file=f)
	print("save '%s.gnu'" % l_md_data, file=f)
	print("exit", file=f)
	f.flush()
	os.wait()	
	return()
	
