#########################################################################################
# Function to write GNU plot macros after optimization
#########################################################################################
def _gnuplot_set_terminal(f, image_type):
	ext = image_type.lower()
	if ext == "ps":
		print("set terminal postscript color solid", file=f)
	elif ext in ("jpg", "jpeg"):
		print("set terminal jpeg size 800,600", file=f)
	elif ext == "gif":
		print("set terminal gif size 800,600", file=f)
	else:
		print("set terminal postscript color solid", file=f)

def gnuplot_macro_2(l_dyna_data,l_title,l_Y_label,l_bmrb,l_image_type):
	f=os.popen('gnuplot','w')
	print("set style data linespoints", file=f)
	_gnuplot_set_terminal(f, l_image_type)
	print("set title '%s'" % l_title, file=f) 
	print("set ylabel '%s'" % l_Y_label, file=f)
	print("set xlabel '%s'" % "Residue number", file=f)
	print("set output '%s_%s.%s'" % (l_bmrb,l_Y_label,l_image_type), file=f)
	print("plot [] '%s' title '%s (%s) ' with linespoints lt 3 pt 6 " % (l_dyna_data,l_Y_label,l_bmrb), file=f)
	print("exit", file=f)
	f.flush()
	os.wait()	
	return()

###################################################################################


def read_plot_series(l_dyna_data):
	result=[]
	data_open=open(l_dyna_data,'r')
	for line in data_open:
		entry=split(line)
		if len(entry)>=2:
			try:
				residue_number=float(entry[0])
				plot_value=float(entry[1])
			except ValueError:
				continue
			residue_label=""
			if len(entry)>=3:
				residue_label=entry[2]
			result=result+[[residue_number,plot_value,residue_label]]
	data_open.close()
	return(result)


def matplotlib_macro_2(l_dyna_data,l_title,l_Y_label,l_bmrb):
	try:
		import matplotlib
		matplotlib.use("Agg")
		from matplotlib import pyplot as plt
	except ImportError:
		print("Warning: matplotlib is not installed; skipping modern plot generation for %s" % l_dyna_data)
		return()

	series=read_plot_series(l_dyna_data)
	if len(series)==0:
		return()

	x_values=[entry[0] for entry in series]
	y_values=[entry[1] for entry in series]
	svg_output='%s_%s.svg' % (l_bmrb,l_Y_label)
	png_output='%s_%s.png' % (l_bmrb,l_Y_label)

	plt.close('all')
	fig, ax = plt.subplots(figsize=(9.5, 5.8), constrained_layout=True)
	fig.patch.set_facecolor('#f6f2e9')
	ax.set_facecolor('#fffdfa')
	ax.plot(x_values, y_values, color='#0b7285', linewidth=2.6, solid_capstyle='round')
	ax.fill_between(x_values, y_values, [min(y_values)] * len(y_values), color='#d9eef2', alpha=0.65)
	ax.scatter(x_values, y_values, s=24, color='#144552', edgecolors='#fffdfa', linewidths=0.7, zorder=3)
	ax.set_title(l_title, fontsize=16, color='#1f2933', pad=14, fontweight='semibold')
	ax.set_xlabel('Residue number', fontsize=11, color='#334e68')
	ax.set_ylabel(l_Y_label.replace('_',' '), fontsize=11, color='#334e68')
	ax.grid(axis='y', color='#d8e2dc', linewidth=0.8)
	ax.spines['top'].set_visible(False)
	ax.spines['right'].set_visible(False)
	ax.spines['left'].set_color('#9fb3c8')
	ax.spines['bottom'].set_color('#9fb3c8')
	ax.tick_params(colors='#486581')
	if len(x_values)>1:
		ax.set_xlim(min(x_values), max(x_values))
	ax.margins(x=0.01, y=0.12)
	fig.savefig(svg_output, format='svg')
	fig.savefig(png_output, format='png', dpi=180)
	plt.close(fig)
	return()

