###################################################################################
# Smoothing function
####################################################################################
def smoothing(L_smooth,L_list,l_atom_type):
	#Building residue number list
	first_residue=0
	last_residue=0
	first_residue_flag=0
	smooth_factor=L_smooth[2]
	central_residue=(smooth_factor//2)+1
	N_terminus_smooth_factor=central_residue
	C_terminus_smooth_factor=smooth_factor//2
	L_all=[]
	############################################
	# To find first and last residues
	############################################
	for L_item in L_list:
		if first_residue_flag==0:
			first_residue=int(L_item[0])
			first_residue_flag=1
		else: 
			last_residue=int(L_item[0])
	###########################################	
	
	#################################################
	# Find residue number offset
	#################################################
	offset=first_residue-1
	
	###################################################	
	# To build a list with residue numbers
	###################################################
	residue_number_list=[]
	for L_number in range(first_residue,(last_residue+1)):
		residue_number_list=residue_number_list+[L_number]
	#if l_atom_type=="N": 
	#	print 	residue_number_list
	###################################################
	counter=0
	list_renew_flag=0
	L_start=0
	L_end=L_smooth[2]
	L_length=len(L_list)
	if len(L_list)>0:
	####################################################
	# Smoothing N_terminus
	####################################################
		Real_first_residue=int(L_list[0][0])
		Real_last_residue=L_list[-1][0]		
		L_chem_shift_diff_list=[]
		L_chem_shift_diff_abs_list=[]
		Old_first_residue=Real_first_residue
		negative_switch=0
		for L_number in range(0,(smooth_factor-N_terminus_smooth_factor)):
			L_chem_shift_diff_list=[]
			L_chem_shift_diff_abs_list=[]
			L_residue_number=int(L_list[L_number][0])
			L_residue_name=L_list[L_number][1]
			L_bmrb_shift=L_list[L_number][2]
			L_simpred_shift=L_list[L_number][3]
			L_chem_shift_diff=L_list[L_number][4]
			L_chem_shift_diff_abs=L_list[L_number][5]
			L_chem_shift_diff_list=L_chem_shift_diff_list+[L_chem_shift_diff]
			L_chem_shift_diff_abs_list=L_chem_shift_diff_abs_list+[L_chem_shift_diff_abs]
			Old_first_residue=L_residue_number
			D_residue_number=L_residue_number
			plus_done=0
			D_counter=1
			while not plus_done:
				D_residue_number=D_residue_number+1
				if  abs(D_residue_number-Old_first_residue)<=central_residue:				
					for L_entry in L_list:				
						N_residue_number=int(L_entry[0])
						if N_residue_number==D_residue_number:
							N_chem_shift_diff=L_entry[4]
							N_chem_shift_diff_abs=L_entry[5]
							L_chem_shift_diff_list=L_chem_shift_diff_list+[N_chem_shift_diff]
							L_chem_shift_diff_abs_list=L_chem_shift_diff_abs_list+[N_chem_shift_diff_abs]
							Old_first_residue=N_residue_number
							D_counter=D_counter+1
							if D_counter==central_residue:
								plus_done=1					
				else: 
					plus_done=1
			if negative_switch==1:
				Old_first_residue=L_residue_number
				D_residue_number=L_residue_number		
				minus_done=0
				D_counter=1
				while not minus_done:		
					D_residue_number=D_residue_number-1
					if  (abs(D_residue_number-Old_first_residue)<=central_residue) and (D_residue_number>0):				
						for L_entry in L_list:				
							N_residue_number=int(L_entry[0])
							if N_residue_number==D_residue_number:
								N_chem_shift_diff=L_entry[4]
								N_chem_shift_diff_abs=L_entry[5]
								L_chem_shift_diff_list=L_chem_shift_diff_list+[N_chem_shift_diff]
								L_chem_shift_diff_abs_list=L_chem_shift_diff_abs_list+[N_chem_shift_diff_abs]
								Old_first_residue=N_residue_number
								D_counter=D_counter+1
								if D_counter==(central_residue-1):
									plus_done=1					
					else: 
						minus_done=1
			N_chem_shift_diff_mean="NONE"			
			if len(L_chem_shift_diff_list)>0:
				N_chem_shift_diff_mean=MLab.mean(L_chem_shift_diff_list)
			N_chem_shift_diff_abs_mean="NONE"
			if len(L_chem_shift_diff_abs_list)>0:	
				N_chem_shift_diff_abs_mean=MLab.mean(L_chem_shift_diff_abs_list)
			N_chem_shift_diff_len=len(L_chem_shift_diff_list)

			L_all=L_all+[[L_residue_number,L_residue_name,L_bmrb_shift,L_simpred_shift,N_chem_shift_diff_mean,N_chem_shift_diff_abs_mean,l_atom_type,N_chem_shift_diff_len,smooth_factor]]
			negative_switch=1

	#######################################################
	
	
	#####################################################	
	# Smoothing main
	#####################################################
		done=0
		while not done:
			#if L_end<(last_residue-offset): Old
			if L_end<=(last_residue-offset): # For Ubiquitin	
				L_chem_shift_diff_list=[]
				L_chem_shift_diff_abs_list=[]
				L_smooth_list=[]		
				missing_chemshift=[]				
				bigger_missing=0
				smaller_missing=0
				new_end=0
				new_start=0
				
				L_residue_number="NONE"
				L_residue_name="NONE"
				L_bmrb_shift="NONE"
				L_simpred_shift="NONE"

				for L_number in residue_number_list[L_start:L_end]:
					found_flag=0
					for L_item in L_list:
						if L_number==int(L_item[0]):
							L_smooth_list=L_smooth_list+[L_item]
							found_flag=1
					if found_flag==0:
						missing_chemshift=missing_chemshift+[L_number]
				more_smaller=0
				more_bigger=0 
				#if (l_atom_type=="CA") and (residue_number_list[L_start:L_end][central_residue-1]==300):
				#	print residue_number_list[L_start:L_end]
				if (len(L_smooth_list)==smooth_factor) and (smooth_factor!=0):			
					L_chem_shift_diff_tmp_list=[]
					L_chem_shift_diff_abs_tmp_list=[]
					L_residue_number=int(L_smooth_list[central_residue-1][0])
					#if (l_atom_type=="CA"):
					#if (L_residue_number==17):					
					#	print l_atom_type, L_start, L_end, L_smooth_list[central_residue-1][0],L_smooth_list					
					#if (L_residue_number==300) and (l_atom_type=="CA"):					
					#	print l_atom_type, L_start, L_end, L_smooth_list[central_residue-1][0],L_smooth_list
					L_residue_name=L_smooth_list[central_residue-1][1]
					L_bmrb_shift=L_smooth_list[central_residue-1][2]
					L_simpred_shift=L_smooth_list[central_residue-1][3]
					for entry in L_smooth_list:
						L_chem_shift_diff=entry[4]
						L_chem_shift_diff_abs=entry[5]
						L_chem_shift_diff_tmp_list=L_chem_shift_diff_tmp_list+[L_chem_shift_diff]
						L_chem_shift_diff_abs_tmp_list=L_chem_shift_diff_abs_tmp_list+[L_chem_shift_diff_abs]
					chem_shift_diff_mean=MLab.mean(L_chem_shift_diff_tmp_list)
					chem_shift_diff_abs_mean=MLab.mean(L_chem_shift_diff_abs_tmp_list)
					chem_shift_len=len(L_chem_shift_diff_tmp_list)
					L_start=L_start+1
					L_end=L_end+1
					L_all=L_all+[[L_residue_number,L_residue_name,L_bmrb_shift,L_simpred_shift,chem_shift_diff_mean,chem_shift_diff_abs_mean,l_atom_type,chem_shift_len,smooth_factor]]
					#if l_atom_type=="CA":
					#	print l_atom_type, L_residue_number, chem_shift_diff_abs_mean, L_chem_shift_diff_abs_tmp_list
				elif (len(L_smooth_list)<smooth_factor):

					L_chem_shift_diff_tmp_list=[]
					L_chem_shift_diff_abs_tmp_list=[]
					L_residue_number=residue_number_list[(L_start):(L_end)][central_residue-1]
					for L_item in L_list:
						if L_residue_number==int(L_item[0]):				
							L_residue_name=L_item[1]
							L_bmrb_shift=L_item[2]
							L_simpred_shift=L_item[3]
					for miss_number in 	missing_chemshift:
						if 	miss_number > L_residue_number:
							bigger_missing=bigger_missing+1
						elif miss_number < L_residue_number:		
							smaller_missing=smaller_missing+1
						elif miss_number == L_residue_number:
							bigger_missing=bigger_missing+1						
					if 	bigger_missing > 0:
						bigger_counter=0
						bigger_flag=0
						new_end=residue_number_list[L_end-1]
						while not bigger_flag:
							new_end=new_end+1
							if new_end<last_residue:
								if new_end<(residue_number_list[L_end]+gap_limit):
									for L_item in L_list:									
										if new_end==L_item[0]:
										
											L_smooth_list=L_smooth_list+[L_item]
											bigger_counter=bigger_counter+1
											if bigger_counter==bigger_missing:
												bigger_flag=1
												
												
								else: 
									bigger_flag=1				
							else:
								more_smaller=bigger_missing-bigger_counter
								bigger_flag=1
					if 	smaller_missing > 0:
						smaller_counter=0
						smaller_flag=0

						new_start=residue_number_list[L_start]
						#if (L_residue_number==300) and (l_atom_type=="CA"):
						#	print "new_start=",new_start
						
						while not smaller_flag:
							new_start=new_start-1
							if new_start>=first_residue:
								if  new_start>=(residue_number_list[L_start]-gap_limit):
									#if (L_residue_number==300) and (l_atom_type=="CA"):
									for L_item in L_list:
										if new_start==L_item[0]:
											L_smooth_list=L_smooth_list+[L_item]
											smaller_counter=smaller_counter+1
											if smaller_counter==smaller_missing:
												smaller_flag=1
								else: 
									smaller_flag=1				
							else:
								more_bigger=smaller_missing-smaller_counter
								smaller_flag=1
				
#					print more_smaller, more_bigger
					#if (l_atom_type=="CA") and (residue_number_list[L_start:L_end][central_residue-1]==300):

					#	print "L_smooth_list after smaller smoothing", L_smooth_list	
					if more_bigger > 0:
						#if (l_atom_type=="CA"):
						#	print residue_number_list[(L_start):(L_end)]
						more_bigger_counter=0
						more_bigger_flag=0
						new_end=residue_number_list[L_end-1]
						while not more_bigger_flag:
							new_end=new_end+1
							if (new_end<=last_residue) and (new_end<(residue_number_list[L_end-1]+gap_limit)):
								for L_item in L_list:
									if new_end==L_item[0]:
										L_smooth_list=L_smooth_list+[L_item]
										more_bigger_counter=more_bigger_counter+1
										if more_bigger_counter==more_bigger:
											more_bigger_flag=1
							else: 
								more_bigger_flag=1
								
								
					#if (l_atom_type=="CA") and (residue_number_list[L_start:L_end][central_residue-1]==300):

					#	print "L_smooth_list after more bigger  smoothing", L_smooth_list				
								
					if more_smaller > 0:
						more_smaller_counter=0
						more_smaller_flag=0
						new_start=residue_number_list[L_start]
						#if (l_atom_type=="CA") and (residue_number_list[L_start:L_end][central_residue-1]==492):
						while not more_smaller_flag:
							#if (l_atom_type=="CA"):
							#	print residue_number_list[(L_start):(L_end)]
							new_start=new_start-1
							
							if (new_start>=first_residue) and (new_start>=residue_number_list[L_start]-gap_limit):
								#if (l_atom_type=="CA") and (residue_number_list[L_start:L_end][central_residue-1]==492):
								#	print "new_start=",new_start, residue_number_list[(L_start):(L_end)], (residue_number_list[L_start]-gap_limit)
								for L_item in L_list:
									if new_start==L_item[0]:
										L_smooth_list=L_smooth_list+[L_item]
										more_smaller_counter=more_smaller_counter+1
										if more_smaller_counter==more_smaller:
											more_smaller_flag=1
							else:
								more_smaller_flag=1

			
					for entry in L_smooth_list:
						L_chem_shift_diff=entry[4]
						L_chem_shift_diff_abs=entry[5]
						L_chem_shift_diff_tmp_list=L_chem_shift_diff_tmp_list+[L_chem_shift_diff]
						L_chem_shift_diff_abs_tmp_list=L_chem_shift_diff_abs_tmp_list+[L_chem_shift_diff_abs]
					chem_shift_diff_mean="NONE"	
					if 	len(L_chem_shift_diff_tmp_list)>0:
						chem_shift_diff_mean=MLab.mean(L_chem_shift_diff_tmp_list)
					chem_shift_diff_abs_mean="NONE"	
					if len(L_chem_shift_diff_abs_tmp_list)>0:	
						chem_shift_diff_abs_mean=MLab.mean(L_chem_shift_diff_abs_tmp_list)
					chem_shift_diff_len=len(L_chem_shift_diff_tmp_list)
					
					#if (l_atom_type=="CA") and (residue_number_list[L_start:L_end][central_residue-1]==300):
					#	print (residue_number_list[L_start:L_end][central_residue-1]),L_residue_number			

					#	print L_residue_number,L_residue_name,L_bmrb_shift,L_simpred_shift,chem_shift_diff_mean,chem_shift_diff_abs_mean,l_atom_type,chem_shift_diff_len,smooth_factor

					
					L_start=L_start+1
					L_end=L_end+1
					if (L_residue_number!=Real_first_residue) and (L_residue_number!=Real_last_residue):	
						L_all=L_all+[[L_residue_number,L_residue_name,L_bmrb_shift,L_simpred_shift,chem_shift_diff_mean,chem_shift_diff_abs_mean,l_atom_type,chem_shift_diff_len,smooth_factor]]

				else:		
					L_chem_shift_diff_tmp_list=[]
					L_chem_shift_diff_abs_tmp_list=[]
					L_residue_number=residue_number_list[L_start:L_end][central_residue-1]
					for L_item in L_list:
						if L_residue_number==int(L_item[0]):			
							L_residue_name=L_item[1]
							L_bmrb_shift=L_item[2]
							L_simpred_shift=L_item[3]
					for entry in L_smooth_list:
						L_chem_shift_diff=entry[4]
						L_chem_shift_diff_abs=entry[5]
						L_chem_shift_diff_tmp_list=L_chem_shift_diff_tmp_list+[L_chem_shift_diff]
						L_chem_shift_diff_abs_tmp_list=L_chem_shift_diff_abs_tmp_list+[L_chem_shift_diff_abs]
					chem_shift_diff_mean="NONE"	
					if 	len(L_chem_shift_diff_tmp_list)>0:
						chem_shift_diff_mean=MLab.mean(L_chem_shift_diff_tmp_list)
					chem_shift_diff_abs_mean="NONE"	
					if len(L_chem_shift_diff_abs_tmp_list)>0:	
						chem_shift_diff_abs_mean=MLab.mean(L_chem_shift_diff_abs_tmp_list)
					chem_shift_diff_len=len(L_chem_shift_diff_tmp_list)
					L_start=L_start+1
					L_end=L_end+1 
					if (L_residue_number!=Real_first_residue) and (L_residue_number!=Real_last_residue):
						L_all=L_all+[[L_residue_number,L_residue_name,L_bmrb_shift,L_simpred_shift,chem_shift_diff_mean,chem_shift_diff_abs_mean,l_atom_type,chem_shift_diff_len,smooth_factor]]
				#if (L_residue_number="NONE") or (L_residue_name="NONE") or (L_bmrb_shift="NONE") or (L_simpred_shift="NONE"):

			else: 
				done=1


	####################################################
	# Smoothing C_terminus
	####################################################
		if smooth_factor!=0:
			negative_switch=0
			L_chem_shift_diff_list=[]
			L_chem_shift_diff_abs_list=[]
			Real_first_residue=int(L_list[0][0])
			Real_last_residue=L_list[1][0]
			Old_first_residue=Real_first_residue
			negative_switch=0
			for L_number in range(1,(smooth_factor-N_terminus_smooth_factor+1)):
				L_chem_shift_diff_list=[]
				L_chem_shift_diff_abs_list=[]
				 
				L_residue_number=int(L_list[-L_number][0])
				L_residue_name=L_list[-L_number][1]
				L_bmrb_shift=L_list[-L_number][2]
				L_simpred_shift=L_list[-L_number][3]
				L_chem_shift_diff=L_list[-L_number][4]
				L_chem_shift_diff_abs=L_list[-L_number][5]
				L_chem_shift_diff_list=L_chem_shift_diff_list+[L_chem_shift_diff]
				L_chem_shift_diff_abs_list=L_chem_shift_diff_abs_list+[L_chem_shift_diff_abs]
				Old_first_residue=L_residue_number
				D_residue_number=L_residue_number
				plus_done=0
				D_counter=1
				while not plus_done:
					D_residue_number=D_residue_number-1
					if  abs(D_residue_number-Old_first_residue)<=central_residue:				
						for L_entry in L_list:				
							N_residue_number=int(L_entry[0])
							if N_residue_number==D_residue_number:
								N_chem_shift_diff=L_entry[4]
								N_chem_shift_diff_abs=L_entry[5]
								L_chem_shift_diff_list=L_chem_shift_diff_list+[N_chem_shift_diff]
								L_chem_shift_diff_abs_list=L_chem_shift_diff_abs_list+[N_chem_shift_diff_abs]
								Old_first_residue=N_residue_number
								D_counter=D_counter+1
								if D_counter==central_residue:
									plus_done=1					
					else: 
						plus_done=1
				if negative_switch==1:
					Old_first_residue=L_residue_number
					D_residue_number=L_residue_number		
					minus_done=0
					D_counter=1
					while not minus_done:	
						D_residue_number=D_residue_number+1
						if (abs(D_residue_number-Old_first_residue)<=central_residue) and (D_residue_number<Real_last_residue):				
							for L_entry in L_list:				
								N_residue_number=int(L_entry[0])
								if N_residue_number==D_residue_number:
									N_chem_shift_diff=L_entry[4]
									N_chem_shift_diff_abs=L_entry[5]
									L_chem_shift_diff_list=L_chem_shift_diff_list+[N_chem_shift_diff]
									L_chem_shift_diff_abs_list=L_chem_shift_diff_abs_list+[N_chem_shift_diff_abs]
									Old_first_residue=N_residue_number
									D_counter=D_counter+1
									if D_counter==(central_residue-1):
										plus_done=1					
						else: 
							minus_done=1
				N_chem_shift_diff_mean="NONE"
				if len(L_chem_shift_diff_list)>0:
					N_chem_shift_diff_mean=MLab.mean(L_chem_shift_diff_list)
				N_chem_shift_diff_abs_mean="NONE"
				if len(L_chem_shift_diff_abs_list):	
					N_chem_shift_diff_abs_mean=MLab.mean(L_chem_shift_diff_abs_list)
				N_chem_shift_diff_len=len(L_chem_shift_diff_list)
				L_all=L_all+[[L_residue_number,L_residue_name,L_bmrb_shift,L_simpred_shift,N_chem_shift_diff_mean,N_chem_shift_diff_abs_mean,l_atom_type,N_chem_shift_diff_len,smooth_factor]]
				negative_switch=1
	#######################################################				
	return(L_all)
##############################################################################################################

###################################################################################
# Smoothing function for final result
####################################################################################
def final_smoothing(L_smooth,L_list):
	#Building residue number list
	first_residue=0
	last_residue=0
	first_residue_flag=0
	smooth_factor=L_smooth
	central_residue=(smooth_factor//2)+1
	N_terminus_smooth_factor=central_residue
	C_terminus_smooth_factor=smooth_factor//2
	N_chem_shift_diff_abs_mean="NONE"
	L_all=[]
	############################################
	# To find first and last residues
	############################################
	for L_item in L_list:
		if first_residue_flag==0:
			first_residue=int(L_item[0])
			first_residue_flag=1
		else: 
			last_residue=int(L_item[0])
	###########################################	
	
	#################################################
	# Find residue number offset
	#################################################
	offset=first_residue-1
	
	###################################################	
	# To build a list with residue numbers
	###################################################
	residue_number_list=[]
	for L_number in range(first_residue,(last_residue+1)):
		residue_number_list=residue_number_list+[L_number]

	###################################################
	counter=0
	list_renew_flag=0
	L_start=0
	L_end=L_smooth
	L_length=len(L_list)
	if len(L_list)>0:
	####################################################
	# Smoothing N_terminus
	####################################################
		Real_first_residue=int(L_list[0][0])
		Real_last_residue=L_list[-1][0]
		L_chem_shift_diff_list=[]
		L_chem_shift_diff_abs_list=[]
		Old_first_residue=Real_first_residue
		negative_switch=0
		L_used_atoms=[]
		L_complete_atoms=[]
		L_abs_or_true="NONE"
		L_first_smooth="NONE"
		for L_number in range(0,(smooth_factor-N_terminus_smooth_factor)):
			L_chem_shift_diff_list=[]
			L_chem_shift_diff_abs_list=[]
			L_residue_number=int(L_list[L_number][0])
			L_residue_name=L_list[L_number][1]
			L_used_atoms=L_list[L_number][1]
			L_chem_shift_diff_abs=L_list[L_number][2]
			L_used_atoms=L_list[L_number][3]
			L_complete_atoms=L_list[L_number][4]
			L_abs_or_true=L_list[L_number][5]
			L_first_smooth=L_list[L_number][6]
			#L_chem_shift_diff_list=L_chem_shift_diff_list+[L_chem_shift_diff]
			if L_chem_shift_diff_abs!="NONE":				
				L_chem_shift_diff_abs_list=L_chem_shift_diff_abs_list+[L_chem_shift_diff_abs]
			Old_first_residue=L_residue_number
			D_residue_number=L_residue_number
			plus_done=0
			D_counter=1
			while not plus_done:
				D_residue_number=D_residue_number+1
				if  abs(D_residue_number-Old_first_residue)<=central_residue:				
					for L_entry in L_list:				
						N_residue_number=int(L_entry[0])
						if N_residue_number==D_residue_number:
							#N_chem_shift_diff=L_entry[4]
							N_chem_shift_diff_abs=L_entry[2]
							#L_chem_shift_diff_list=L_chem_shift_diff_list+[N_chem_shift_diff]
							if N_chem_shift_diff_abs!="NONE":
								L_chem_shift_diff_abs_list=L_chem_shift_diff_abs_list+[N_chem_shift_diff_abs]
							Old_first_residue=N_residue_number
							D_counter=D_counter+1
							if D_counter==central_residue:
								plus_done=1					
				else: 
					plus_done=1
			if negative_switch==1:
				Old_first_residue=L_residue_number
				D_residue_number=L_residue_number		
				minus_done=0
				D_counter=1
				while not minus_done:		
					D_residue_number=D_residue_number-1
					if  (abs(D_residue_number-Old_first_residue)<=central_residue) and (D_residue_number>0):				
						for L_entry in L_list:				
							N_residue_number=int(L_entry[0])
							if N_residue_number==D_residue_number:
								#N_chem_shift_diff=L_entry[4]
								N_chem_shift_diff_abs=L_entry[2]
								#L_chem_shift_diff_list=L_chem_shift_diff_list+[N_chem_shift_diff]
								if N_chem_shift_diff_abs!="NONE":
									L_chem_shift_diff_abs_list=L_chem_shift_diff_abs_list+[N_chem_shift_diff_abs]
								Old_first_residue=N_residue_number
								D_counter=D_counter+1
								if D_counter==(central_residue-1):
									plus_done=1					
					else: 
						minus_done=1
			if len(L_chem_shift_diff_abs_list)>0:
				N_chem_shift_diff_abs_mean=MLab.mean(L_chem_shift_diff_abs_list)
			#N_chem_shift_diff_mean=MLab.mean(L_chem_shift_diff_list)			
			#N_chem_shift_diff_len=len(L_chem_shift_diff_list)
				L_all=L_all+[[L_residue_number,L_residue_name,N_chem_shift_diff_abs_mean,L_used_atoms,L_complete_atoms,L_abs_or_true,L_first_smooth]]
			negative_switch=1

	#######################################################
	
	
	#####################################################	
	# Smoothing main
	#####################################################
		done=0
		while not done:
			chem_shift_diff_abs_mean="NONE"
			if L_end<=(last_residue-offset): #For Ubiquitin
			
				L_chem_shift_diff_list=[]
				L_chem_shift_diff_abs_list=[]
				L_smooth_list=[]		
				missing_chemshift=[]				
				bigger_missing=0
				smaller_missing=0
				new_end=0
				new_start=0
				L_residue_number="NONE"
				L_residue_name="NONE"
				#L_bmrb_shift="NONE"
				#L_simpred_shift="NONE"
				chem_shift_diff_mean="NONE"
				chem_shift_diff_abs_mean="NONE"
				for L_number in residue_number_list[L_start:L_end]:
					found_flag=0
					for L_item in L_list:
						if (L_number==int(L_item[0])) and (L_item[2]!="NONE"):
							L_smooth_list=L_smooth_list+[L_item]
							found_flag=1
					if found_flag==0:
						missing_chemshift=missing_chemshift+[L_number]
				more_smaller=0
				more_bigger=0 	

				if len(L_smooth_list)==smooth_factor:
							
					L_chem_shift_diff_tmp_list=[]
					L_chem_shift_diff_abs_tmp_list=[]
					L_residue_number=int(L_smooth_list[central_residue-1][0])
					L_residue_name=L_smooth_list[central_residue-1][1]
					#L_bmrb_shift=L_smooth_list[central_residue-1][2]
					#L_simpred_shift=L_smooth_list[central_residue-1][3]
					L_used_atoms=L_smooth_list[central_residue-1][3]
					L_complete_atoms=L_smooth_list[central_residue-1][4]
					L_abs_or_true=L_smooth_list[central_residue-1][5]
					L_first_smooth=L_smooth_list[central_residue-1][6]
									
					for entry in L_smooth_list:
						#L_chem_shift_diff=entry[4]
						L_chem_shift_diff_abs=entry[2]

						#L_chem_shift_diff_tmp_list=L_chem_shift_diff_tmp_list+[L_chem_shift_diff]
						if L_chem_shift_diff_abs!="NONE":
							L_chem_shift_diff_abs_tmp_list=L_chem_shift_diff_abs_tmp_list+[L_chem_shift_diff_abs]

					#chem_shift_diff_mean=MLab.mean(L_chem_shift_diff_tmp_list)
					if len(L_chem_shift_diff_abs_tmp_list)>0:
						chem_shift_diff_abs_mean=MLab.mean(L_chem_shift_diff_abs_tmp_list)
						L_all=L_all+[[L_residue_number,L_residue_name,chem_shift_diff_abs_mean,L_used_atoms,L_complete_atoms,L_abs_or_true,L_first_smooth]]
	

					#chem_shift_len=len(L_chem_shift_diff_tmp_list)
					
					L_start=L_start+1
					L_end=L_end+1
					
					
				elif (len(L_smooth_list)<smooth_factor):
					#L_chem_shift_diff_tmp_list=[]
					L_chem_shift_diff_abs_tmp_list=[]
					
					#L_residue_number=residue_number_list[(L_start-offset):(L_end-offset)][central_residue-1]

					L_residue_number=residue_number_list[(L_start):(L_end)][central_residue-1]

					for L_item in L_list:
						if L_residue_number==int(L_item[0]):				
							L_residue_name=L_item[1]
							L_used_atoms=L_item[3]
							L_complete_atoms=L_item[4]
							L_abs_or_true=L_item[5]
							L_first_smooth=L_item[6]
							
							#L_bmrb_shift=L_item[2]
							#L_simpred_shift=L_item[3]
					for miss_number in 	missing_chemshift:
#						print miss_number, L_residue_number
						if 	miss_number > L_residue_number:
							bigger_missing=bigger_missing+1
						elif miss_number < L_residue_number:		
							smaller_missing=smaller_missing+1
						elif miss_number == L_residue_number:
							bigger_missing=bigger_missing+1	
#					print bigger_missing, smaller_missing											
					if 	bigger_missing > 0:
						bigger_counter=0
						bigger_flag=0
						#new_end=L_end
						new_end=residue_number_list[L_end-1]
						while not bigger_flag:
							new_end=new_end+1
							if new_end<=last_residue:
								if new_end<(residue_number_list[L_end]+gap_limit):
									for L_item in L_list:
										if (new_end==L_item[0]) and (L_item[2]!="NONE"):
											L_smooth_list=L_smooth_list+[L_item]
											bigger_counter=bigger_counter+1
											if (bigger_counter==bigger_missing):
												bigger_flag=1

								else: 
									bigger_flag=1			

							else:
								more_smaller=bigger_missing-bigger_counter
								bigger_flag=1



					if 	smaller_missing > 0:
						smaller_counter=0
						smaller_flag=0
						new_start=residue_number_list[L_start]
						while not smaller_flag:
							new_start=new_start-1
							if new_start>=first_residue:
								if  new_start>=(residue_number_list[L_start]-gap_limit):
									for L_item in L_list:
										if (new_start==L_item[0]) and (L_item[2]!="NONE"):
											L_smooth_list=L_smooth_list+[L_item]
											smaller_counter=smaller_counter+1
											if (smaller_counter==smaller_missing):
												smaller_flag=1
								else: 
									smaller_flag=1				


							else:
								more_bigger=smaller_missing-smaller_counter
								smaller_flag=1
				

#					print more_smaller, more_bigger
					if more_bigger > 0:
						more_bigger_counter=0
						more_bigger_flag=0
						new_end=residue_number_list[L_end]
						while not more_bigger_flag:
							new_end=new_end+1
							if (new_end<=last_residue) and (new_end<(residue_number_list[L_end]+gap_limit)):
								for L_item in L_list:
									if (new_end==L_item[0]) and (L_item[2]!="NONE"):
										L_smooth_list=L_smooth_list+[L_item]
										more_bigger_counter=more_bigger_counter+1
										if (more_bigger_counter==more_bigger):
											more_bigger_flag=1
							else: 
								more_bigger_flag=1
								
					if more_bigger > 0:
						#if (l_atom_type=="CA"):
						#	print residue_number_list[(L_start):(L_end)]
						more_bigger_counter=0
						more_bigger_flag=0
						new_end=residue_number_list[L_end]
						while not more_bigger_flag:
							new_end=new_end+1
							if (new_end<=last_residue) and (new_end<(residue_number_list[L_end]+gap_limit)):
								for L_item in L_list:
									if new_end==L_item[0]:
										L_smooth_list=L_smooth_list+[L_item]
										more_bigger_counter=more_bigger_counter+1
										if more_bigger_counter==more_bigger:
											more_bigger_flag=1
							else: 
								more_bigger_flag=1
								
																
								
								
								
					if more_smaller > 0:
						more_smaller_counter=0
						more_smaller_flag=0
						new_start=residue_number_list[L_start]
						while not more_smaller_flag:
							new_start=new_start-1
							if (new_start>=first_residue) and (new_start>=residue_number_list[L_start]-gap_limit):
								for L_item in L_list:
									if (new_start==L_item[0]) and (L_item[2]!="NONE"):
										L_smooth_list=L_smooth_list+[L_item]
										more_smaller_counter=more_smaller_counter+1
										if (more_smaller_counter==more_smaller):
											more_smaller_flag=1
							else:
								more_smaller_flag=1
								

								
					for entry in L_smooth_list:
						#L_chem_shift_diff=entry[4]
						L_chem_shift_diff_abs=entry[2]
						#L_chem_shift_diff_tmp_list=L_chem_shift_diff_tmp_list+[L_chem_shift_diff]
						if L_chem_shift_diff_abs!="NONE":
							L_chem_shift_diff_abs_tmp_list=L_chem_shift_diff_abs_tmp_list+[L_chem_shift_diff_abs]
						
					#chem_shift_diff_mean=MLab.mean(L_chem_shift_diff_tmp_list)
					if (len(L_chem_shift_diff_abs_tmp_list)>0) and (L_residue_number!=Real_first_residue) and (L_residue_number!=Real_last_residue):
						chem_shift_diff_abs_mean=MLab.mean(L_chem_shift_diff_abs_tmp_list)
						L_all=L_all+[[L_residue_number,L_residue_name,chem_shift_diff_abs_mean,L_used_atoms,L_complete_atoms,L_abs_or_true,L_first_smooth]]
					
					#chem_shift_diff_len=len(L_chem_shift_diff_tmp_list)
					L_start=L_start+1
					L_end=L_end+1
					
					#L_all=L_all+[[L_residue_number,L_residue_name,L_bmrb_shift,L_simpred_shift,chem_shift_diff_mean,chem_shift_diff_abs_mean,chem_shift_diff_len,smooth_factor]]
					

				else:		
					#L_chem_shift_diff_tmp_list=[]
					L_chem_shift_diff_abs_tmp_list=[]
					L_residue_number=residue_number_list[L_start:L_end][central_residue-1]
					for L_item in L_list:
						if L_residue_number==int(L_item[0]):			
							L_residue_name=L_item[1]
							L_used_atoms=L_item[3]
							L_complete_atoms=L_item[4]
							L_abs_or_true=L_item[5]
							L_first_smooth=L_item[6]
							#L_bmrb_shift=L_item[2]
							#L_simpred_shift=L_item[3]
					for entry in L_smooth_list:
						#L_chem_shift_diff=entry[4]
						L_chem_shift_diff_abs=entry[2]
						#L_chem_shift_diff_tmp_list=L_chem_shift_diff_tmp_list+[L_chem_shift_diff]
						if L_chem_shift_diff_abs!="NONE":
							L_chem_shift_diff_abs_tmp_list=L_chem_shift_diff_abs_tmp_list+[L_chem_shift_diff_abs]
						
					if (len(L_chem_shift_diff_abs_tmp_list)>0) and (L_residue_number!=Real_first_residue) and (L_residue_number!=Real_last_residue):
						#chem_shift_diff_mean=MLab.mean(L_chem_shift_diff_tmp_list)
						chem_shift_diff_abs_mean=MLab.mean(L_chem_shift_diff_abs_tmp_list)
						L_all=L_all+[[L_residue_number,L_residue_name,chem_shift_diff_abs_mean,L_used_atoms,L_complete_atoms,L_abs_or_true,L_first_smooth]]
					
						#chem_shift_len=len(L_chem_shift_diff_tmp_list)
					L_start=L_start+1
					L_end=L_end+1 
					#L_all=L_all+[[L_residue_number,L_residue_name,L_bmrb_shift,L_simpred_shift,chem_shift_diff_mean,chem_shift_diff_abs_mean,chem_shift_len,smooth_factor]]
					
			else: 
				done=1
				
				
				
	####################################################
	# Smoothing C_terminus
	####################################################
		negative_switch=0
		L_chem_shift_diff_list=[]
		L_chem_shift_diff_abs_list=[]
		Real_first_residue=int(L_list[0][0])
		Real_last_residue=L_list[1][0]
		Old_first_residue=Real_first_residue
		negative_switch=0
		for L_number in range(1,(smooth_factor-N_terminus_smooth_factor+1)):
			L_chem_shift_diff_list=[]
			L_chem_shift_diff_abs_list=[]
			L_residue_number=int(L_list[-L_number][0])
			L_residue_name=L_list[-L_number][1]
			L_chem_shift_diff_abs=L_list[-L_number][2]

			L_used_atoms=L_list[-L_number][3]
			L_complete_atoms=L_list[-L_number][4]
			L_abs_or_true=L_list[-L_number][5]
			L_first_smooth=L_list[-L_number][6]
			if L_chem_shift_diff_abs!="NONE":
				L_chem_shift_diff_abs_list=L_chem_shift_diff_abs_list+[L_chem_shift_diff_abs]
			Old_first_residue=L_residue_number
			D_residue_number=L_residue_number
			plus_done=0
			D_counter=1
			while not plus_done:
				D_residue_number=D_residue_number-1
				if  abs(D_residue_number-Old_first_residue)<=central_residue:				
					for L_entry in L_list:				
						N_residue_number=int(L_entry[0])
						if N_residue_number==D_residue_number:
							#N_chem_shift_diff=L_entry[4]
							N_chem_shift_diff_abs=L_entry[2]
							#L_chem_shift_diff_list=L_chem_shift_diff_list+[N_chem_shift_diff]
							if N_chem_shift_diff_abs!="NONE":
								L_chem_shift_diff_abs_list=L_chem_shift_diff_abs_list+[N_chem_shift_diff_abs]
							Old_first_residue=N_residue_number
							D_counter=D_counter+1
							if D_counter==central_residue:
								plus_done=1					
				else: 
					plus_done=1
			if negative_switch==1:
				Old_first_residue=L_residue_number
				D_residue_number=L_residue_number		
				minus_done=0
				D_counter=1
				while not minus_done:	
					D_residue_number=D_residue_number+1
					if (abs(D_residue_number-Old_first_residue)<=central_residue) and (D_residue_number<Real_last_residue):				
						for L_entry in L_list:				
							N_residue_number=int(L_entry[0])
							if N_residue_number==D_residue_number:
								#N_chem_shift_diff=L_entry[4]
								N_chem_shift_diff_abs=L_entry[2]
								
								#L_chem_shift_diff_list=L_chem_shift_diff_list+[N_chem_shift_diff]
								if N_chem_shift_diff_abs!="NONE":
									L_chem_shift_diff_abs_list=L_chem_shift_diff_abs_list+[N_chem_shift_diff_abs]
								Old_first_residue=N_residue_number
								D_counter=D_counter+1
								if D_counter==(central_residue-1):
									plus_done=1					
					else: 
						minus_done=1
	
			#N_chem_shift_diff_mean=MLab.mean(L_chem_shift_diff_list)
			if len(L_chem_shift_diff_abs_list)>0:
				N_chem_shift_diff_abs_mean=MLab.mean(L_chem_shift_diff_abs_list)
				L_all=L_all+[[L_residue_number,L_residue_name,N_chem_shift_diff_abs_mean,L_used_atoms,L_complete_atoms,L_abs_or_true,L_first_smooth]]
			
			#N_chem_shift_diff_len=len(L_chem_shift_diff_list)
			
			#L_all=L_all+[[L_residue_number,L_residue_name,L_bmrb_shift,L_simpred_shift,N_chem_shift_diff_mean,N_chem_shift_diff_abs_mean,N_chem_shift_diff_len,smooth_factor]]
					
			negative_switch=1
	#######################################################				
	return(L_all)
##############################################################################################################

###################################################################################
# Gap filling function when smooth=0, either  i+n or i-n
####################################################################################

def gap_fill(L_list,l_residue_number_list,l_atom):
	L_all=[]
	if len(L_list)>0:
		done=0
		while not done:
			L_chem_shift_diff_list=[]
			L_chem_shift_diff_abs_list=[]
			L_residue_number="NONE"
			L_residue_name="NONE"
			L_bmrb_shift="NONE"
			L_simpred_shift="NONE"
			L_atom_type="NONE"
			for L_aa in l_residue_number_list:
				L_residue_number_found=0
				L_residue_number=int(L_aa[1])
				L_residue_name=aa_names_full_all_CAP[L_aa[0][0:3]]
				while not  L_residue_number_found:
					for L_item in L_list:
						if (L_residue_number==int(L_item[0])) and (L_residue_name==L_item[1]) and (l_atom==L_item[6]):
							L_residue_number_found=1
							L_bmrb_shift=L_item[2]
							L_simpred_shift=L_item[3]
							L_chem_shift_diff=L_item[4]
							L_chem_shift_diff_abs=L_item[5]
							L_atom_type=L_item[6]
							chem_shift_diff_len=0
							L_all=L_all+[[L_residue_number,L_residue_name,L_bmrb_shift,L_simpred_shift,L_chem_shift_diff,L_chem_shift_diff_abs,L_atom_type]]
					#if ((L_residue_name=="G") and (l_atom=="CB")) or ((L_residue_name=="P") and (l_atom=="N")):			
					#	L_residue_number_found=1									
					if L_residue_number_found==0:
						
						for i in range(1,gap_limit+1):
							if L_residue_number_found==0:
								positive_found=0
								negative_found=0
								for L_item in L_list:
									if ((L_residue_number+i)==int(L_item[0])) and (l_atom==L_item[6]):
										L_residue_number_found=1 
										positive_found=1
										L_bmrb_shift=L_item[2]
										L_simpred_shift=L_item[3]
										L_chem_shift_diff=L_item[4]
										L_chem_shift_diff_abs=L_item[5]
										L_atom_type=L_item[6]
										chem_shift_diff_len=0
										L_all=L_all+[[L_residue_number,L_residue_name,L_bmrb_shift,L_simpred_shift,L_chem_shift_diff,L_chem_shift_diff_abs,L_atom_type]]
									

								if 	positive_found==0:
									for L_item in L_list:
										if ((L_residue_number-i)==int(L_item[0])) and (l_atom==L_item[6]):
											L_residue_number_found=1 
											negative_found=1
											L_bmrb_shift=L_item[2]
											L_simpred_shift=L_item[3]
											L_chem_shift_diff=L_item[4]
											L_chem_shift_diff_abs=L_item[5]
											L_atom_type=L_item[6]
											chem_shift_diff_len=0
											L_all=L_all+[[L_residue_number,L_residue_name,L_bmrb_shift,L_simpred_shift,L_chem_shift_diff,L_chem_shift_diff_abs,L_atom_type]]
																							
											
								else: 
									L_residue_number_found=1			
						else: 
							L_residue_number_found=1
									 												 		
			else: 
				done=1					
										
							

				
	return(L_all)
##############################################################################################################

##############################################################################################################
# Gap filling function when smooth=0, uses averaging of i+n and i-n
####################################################################################
def gap_fill2(L_list,l_residue_number_list,l_atom):
	L_all=[]
	if len(L_list)>0:
		done=0
		while not done:
			L_chem_shift_diff_list=[]
			L_chem_shift_diff_abs_list=[]
			L_smooth_list=[]		
			missing_chemshift=[]				
			L_residue_number="NONE"
			L_residue_name="NONE"
			L_bmrb_shift="NONE"
			L_simpred_shift="NONE"
			L_atom_type="NONE"
			for L_aa in l_residue_number_list:
				L_residue_number_found=0
				L_residue_number=int(L_aa[1])
				L_residue_name=aa_names_full_all_CAP[L_aa[0][0:3]]	
				while not  L_residue_number_found:
					for L_item in L_list:
						if (L_residue_number==int(L_item[0])) and (L_residue_name==L_item[1]) and (l_atom==L_item[6]):
							L_residue_number_found=1
							L_bmrb_shift=L_item[2]
							L_simpred_shift=L_item[3]
							L_chem_shift_diff=L_item[4]
							L_chem_shift_diff_abs=L_item[5]
							L_atom_type=L_item[6]
							chem_shift_diff_len=0
							L_all=L_all+[[L_residue_number,L_residue_name,L_bmrb_shift,L_simpred_shift,L_chem_shift_diff,L_chem_shift_diff_abs,L_atom_type]]
					#if ((L_residue_name=="G") and (l_atom=="CB")) or ((L_residue_name=="P") and (l_atom=="N")):			
					#	L_residue_number_found=1				
					if (L_residue_number_found==0) and (L_residue_number>=real_BMRB_first_res) and (L_residue_number<=real_BMRB_last_res): 
						positive_found=0
						negative_found=0
						pos_neg_list_true=[]
						pos_neg_list_abs=[]
						pos_neg_list_true_ave="NONE"
						pos_neg_list_abs_ave="NONE"
						for i in range(1,gap_limit+1):
							if L_residue_number_found==0:
								if positive_found!=1:
									for L_item in L_list:
										if ((L_residue_number+i)==int(L_item[0])) and (l_atom==L_item[6]):
											positive_found=1
											L_chem_shift_diff=L_item[4]
											L_chem_shift_diff_abs=L_item[5]
											pos_neg_list_abs=pos_neg_list_abs+[L_chem_shift_diff_abs]
											pos_neg_list_true=pos_neg_list_true+[L_chem_shift_diff]
								if negative_found!=1:
									for L_item in L_list:
										if ((L_residue_number-i)==int(L_item[0])) and (l_atom==L_item[6]):
											negative_found=1													
											L_chem_shift_diff=L_item[4]
											L_chem_shift_diff_abs=L_item[5]
											pos_neg_list_abs=pos_neg_list_abs+[L_chem_shift_diff_abs]
											pos_neg_list_true=pos_neg_list_true+[L_chem_shift_diff]													

												 													
						if (negative_found==1) or (positive_found==1):
							if len(pos_neg_list_abs)>0:																
								pos_neg_list_abs_ave=MLab.mean(pos_neg_list_abs)
							if len(pos_neg_list_true)>0:
								pos_neg_list_true_ave=MLab.mean(pos_neg_list_true)
							L_residue_number_found=1																										
							L_bmrb_shift=L_item[2]
							L_simpred_shift=L_item[3]
							L_chem_shift_diff=pos_neg_list_true_ave
							L_chem_shift_diff_abs=pos_neg_list_abs_ave
							L_atom_type=L_item[6]
							chem_shift_diff_len=0
							L_all=L_all+[[L_residue_number,L_residue_name,L_bmrb_shift,L_simpred_shift,L_chem_shift_diff,L_chem_shift_diff_abs,L_atom_type]]

						else: 
							L_residue_number_found=1
					else: 
						L_residue_number_found=1							 												 		
			else: 
				done=1					
										
									 												 		
	else: 
		done=1											

				
	return(L_all)
