################################################################################
#Create primary sequence from BMRB file
##############################################################################
def bmrb_to_aa(l_bmrb_entry,l_selected_entity_id=None):
	sequences_by_entity={}
	loop_list=l_bmrb_entry.get_loops_by_category("_Entity_poly_seq")
	if len(loop_list)==0:
		print("""\n ERROR: No _Entity_poly_seq loop was found in the NMR-STAR file.\n: """)
		sys.exit(1)
	for loop_obj in loop_list:
		tag_map=_loop_tag_map(loop_obj)
		res_num_tag=None
		for candidate_tag in ["Comp_index_ID","Num","Seq_ID"]:
			if candidate_tag in tag_map:
				res_num_tag=candidate_tag
				break
		if (res_num_tag is None) or ("Mon_ID" not in tag_map):
			continue
		entity_id_tag="Entity_ID" if "Entity_ID" in tag_map else None
		for row in loop_obj.data:
			res_num=_normalize_nmrstar_value(row[tag_map[res_num_tag]])
			res_name=_normalize_nmrstar_value(row[tag_map["Mon_ID"]])
			if (res_num is None) or (res_name is None):
				continue
			try:
				res_num_int=int(float(res_num))
			except ValueError:
				continue
			row_entity_id=_normalize_entity_id(row[tag_map[entity_id_tag]]) if entity_id_tag is not None else "1"
			if row_entity_id is None:
				row_entity_id="1"
			if row_entity_id not in sequences_by_entity:
				sequences_by_entity[row_entity_id]={}
			if res_num_int not in sequences_by_entity[row_entity_id]:
				sequences_by_entity[row_entity_id][res_num_int]=res_name
	selected_entity_id_local=_select_entity_id(sequences_by_entity,l_selected_entity_id)
	aa_res_name_num_dic=sequences_by_entity[selected_entity_id_local]
	aa_res_name_num_list=[]
	for res_num_int in sorted(aa_res_name_num_dic):
		aa_res_name_num_list=aa_res_name_num_list+[[aa_res_name_num_dic[res_num_int],str(res_num_int)]]
	return(aa_res_name_num_list)
#####################################################################################


#################################################################################
# Read sec structure from CSI output
#################################################################################
def read_csi(l_csi_result):
	csi_open=open(l_csi_result,'r')
	Lines = csi_open.readlines()
	csi_open.close()
	sec_str_list=[]
	helix_start=[]
	helix_end=[]
	beta_start=[]
	beta_end=[]
	helix_start_flag=0
	helix_end_flag=0
	beta_start_flag=0
	beta_end_flag=0
	random_flag=0
	for line in Lines:
		line_split=split(line)
		read_flag=0
		if len(line_split)>=1:		
			residue_num=line_split[0]
			residue_name=line_split[1]
			sec_str_type=line_split[-1]
			sec_str_list=sec_str_list+[[residue_num,residue_name,sec_str_type]]
			if (sec_str_type=="H") and (helix_start_flag==0):
				helix_start=helix_start+[[residue_num,residue_name,sec_str_type]]
				helix_start_flag=1
			elif (sec_str_type=="H") and (helix_start_flag==1):
				helix_end_tmp=[residue_num,residue_name,sec_str_type]
			elif (sec_str_type!="H") and (helix_start_flag==1):
				helix_end=helix_end+[helix_end_tmp]
				helix_start_flag=0			
			elif (sec_str_type=="B") and (beta_start_flag==0):
				beta_start=beta_start+[[residue_num,residue_name,sec_str_type]]
				beta_start_flag=1
			if (sec_str_type=="B") and (beta_start_flag==1):
				beta_end_tmp=[residue_num,residue_name,sec_str_type]
			elif (sec_str_type!="B") and (beta_start_flag==1):
				beta_end=beta_end+[beta_end_tmp]
				beta_start_flag=0
	return(sec_str_list)	
#	return(sec_str_list,helix_start,helix_end,beta_start,beta_end)				
