######################################################################################
# Function1 to correct sigma for end effects
######################################################################################
def end_effect(l_list,l_N_term_coef,l_C_term_coef,l_N_term_res_num,l_C_term_res_num,l_N_term_low,l_N_term_high,l_C_term_low,l_C_term_high,l_first,l_last):
	result_list=[]
	l_N_switch=l_C_switch=0
	l_N_end_list=l_C_end_list=[]
	l_N_mean=l_C_mean=9999	
	l_file_out="%s/N_C_average"	% top_directory
	l_file_out_open=open(l_file_out,"w")
	for l_item in l_list:
		l_res_num,l_sigma=int(l_item[0]),l_item[2]
		if (abs(l_res_num-l_first)<=4): # 4 for DnaB
			l_N_end_list=l_N_end_list+[l_sigma]
		elif (abs(l_last-l_res_num)<=4): #4 for DnaB
			l_C_end_list=l_C_end_list+[l_sigma]
	if len(l_N_end_list)>0:
		l_N_mean=MLab.mean(l_N_end_list)
		l_N_mean_out="%s N_term %s %s %s %s %s %s %s %s %s %s %s %s" % (l_N_mean,bmrb_file,md_file,nameoffile,corr_suff,end_corr_suff,no_fl_suff,RC_author,preceed_res_effect_name,next_res_effect_name,neighbor_name,smooth,final_smooth) + linesep
		l_file_out_open.write(l_N_mean_out)	
	if len(l_C_end_list)>0:
		l_C_mean=MLab.mean(l_C_end_list)
		l_C_mean_out="%s C_term %s %s %s %s %s %s %s %s %s %s %s %s" % (l_C_mean,bmrb_file,md_file,nameoffile,corr_suff,end_corr_suff,no_fl_suff,RC_author,preceed_res_effect_name,next_res_effect_name,neighbor_name,smooth,final_smooth) + linesep
		l_file_out_open.write(l_C_mean_out)
	if (l_N_mean>l_N_term_low) and (l_N_mean<l_N_term_high):
		l_N_switch=1

	if (l_C_mean>l_C_term_low) and (l_C_mean<l_C_term_high):
		l_C_switch=1						
	for l_item in l_list:
		l_res_num,l_res_name,l_sigma,l_atomlist1,l_atomlist2,l_abs_or_true,l_smooth=int(l_item[0]),l_item[1],l_item[2],l_item[3],l_item[4],l_item[5],l_item[6]
		if (abs(l_res_num-l_first)<=l_N_term_res_num) and (l_N_switch==1):
			l_sigma=l_sigma*l_N_term_coef*10
			l_item[2]=l_sigma
			result_list=result_list+[l_item]
		elif (abs(l_last-l_res_num)<=l_C_term_res_num) and (l_C_switch==1):
			l_sigma=l_sigma*l_C_term_coef*10
			l_item[2]=l_sigma
			result_list=result_list+[l_item]
		else:
			result_list=result_list+[l_item]	
	l_file_out_open.close()											
	return(result_list)	

