######################################################################################
# Function3 to correct sigma for end effects
######################################################################################
def end_effect3(l_list,l_N_term_coef,l_C_term_coef,l_N_term_res_num,l_C_term_res_num,l_N_term_low,l_N_term_high,l_C_term_low,l_C_term_high,l_first,l_last):
	result_list=[]
	l_N_switch=l_C_switch=0
	l_N_end_list=l_C_end_list=[]
	l_N_max="NONE"
	l_C_max="NONE"
	for l_item in l_list:
		l_res_num,l_sigma=int(l_item[0]),l_item[2]
		if (abs(l_res_num-l_first)<=4): # 4 for DnaB
			l_N_end_list=l_N_end_list+[[l_sigma,l_res_num]]
		elif (abs(l_last-l_res_num)<=4): #4 for DnaB
			l_C_end_list=l_C_end_list+[[l_sigma,l_res_num]]
	if len(l_N_end_list)>0:
		l_N_max=l_N_end_list[0][0]
		l_N_max_place=l_N_end_list[0][1]
		for l_N_end_list_item in l_N_end_list:
			if 	l_N_end_list_item[0]>l_N_max:
				l_N_max=l_N_end_list_item[0]
				l_N_max_place=int(l_N_end_list_item[1])

	if len(l_C_end_list)>0:
		l_C_max=l_C_end_list[0][0]
		l_C_max_place=l_C_end_list[0][1]
		for l_C_end_list_item in l_C_end_list:
			if 	l_C_end_list_item[0]>l_C_max:
				l_C_max=l_C_end_list_item[0]
				l_C_max_place=int(l_C_end_list_item[1])			
	for l_item in l_list:
		l_res_num,l_res_name,l_sigma,l_atomlist1,l_atomlist2,l_abs_or_true,l_smooth=int(l_item[0]),l_item[1],float(l_item[2]),l_item[3],l_item[4],l_item[5],l_item[6]	
		if (abs(l_res_num-l_first)<=3): # 4 for DnaB
			if (l_N_max!="NONE") and (l_sigma<l_N_max) and (l_res_num<l_N_max_place):				
				l_N_diff=l_sigma-l_N_max
				l_sigma=l_sigma+(abs(l_N_diff)*2)
				if l_sigma>floor_value2:
					l_sigma=floor_value2
				l_item[2]=l_sigma
				result_list=result_list+[l_item]
			else:
				result_list=result_list+[l_item]
		elif (abs(l_last-l_res_num)<=3): #4 for DnaB			
			if (l_C_max!="NONE") and (l_sigma<l_C_max) and (l_res_num>l_C_max_place):				
				l_C_diff=l_sigma-l_C_max
				l_sigma=l_sigma+(abs(l_C_diff)*2)
				if l_sigma>floor_value2:
					l_sigma=floor_value2
				l_item[2]=l_sigma
				result_list=result_list+[l_item]
			else:
				result_list=result_list+[l_item]
		else:
			result_list=result_list+[l_item]										
	return(result_list)	

