##########################################
# A function to find first and last residues
############################################
def first_and_last(l_list):
	first_residue_flag=0
	for l_item in l_list:
		if first_residue_flag==0:
			l_first_residue=int(l_item[1])
			first_residue_flag=1
		else: 
			l_last_residue=int(l_item[1])
	return(l_first_residue,l_last_residue)		
