# Function to do a grid search
#########################################################################################################

def grid_search(l_increment,l_firstresidue,l_lastresidue,l_all_atoms_smooth,l_directory,smooth_type,lCOp_list,lCAp_list,lCBp_list,lHAp_list,lHp_list,lNp_list,lgridsearch_list,lgrid_search_flag,lCOp_exclude,lCAp_exclude,lCBp_exclude,lHAp_exclude,lHp_exclude,lNp_exclude,lCA_Hertz_corr,lN_Hertz_corr,lH_Hertz_corr,lfunction_flag,l_atom_list,nBMRB_offset,lpic_flag,s_dir_for_pic,s_preceed,s_next,s_RC,s_neighb,s_corrcoef,s_final_smooth):
	grid_search_counter=0
	count_try=0		
	list_of_files=[]										
	CA_CB_CO_HA_all_residues_true_corr=[]
	CA_CB_CO_all_residues_true_corr=[]
	CA_CB_HA_all_residues_true_corr=[]
