	CB_all_residues_true_corr=[]
	CO_all_residues_true_corr=[]
	HA_all_residues_true_corr=[]

	CA_CB_CO_HA_all_residues_abs_corr=[]
	#CA_CB_CO_HA_all_residues_abs_reg=[]
	CA_CB_CO_all_residues_abs_corr=[]
	#CA_CB_CO_all_residues_abs_reg=[]
	#CA_CB_HA_all_residues_abs_reg=[]
	CA_CB_HA_all_residues_abs_corr=[]
	HA_CB_CO_all_residues_abs_corr=[]
	#HA_CB_CO_all_residues_abs_reg=[]
	CA_CB_all_residues_abs_corr=[]
	#CA_CB_all_residues_abs_reg=[]
	CA_CO_all_residues_abs_corr=[]
	#CA_CO_all_residues_abs_reg=[]
	CO_CB_all_residues_abs_corr=[]
	#CO_CB_all_residues_abs_reg=[]
	CA_HA_all_residues_abs_corr=[]
	#CA_HA_all_residues_abs_reg=[]
	CB_HA_all_residues_abs_corr=[]
	#CB_HA_all_residues_abs_reg=[]
	CO_HA_all_residues_abs_corr=[]
	#CO_HA_all_residues_abs_reg=[]
	CA_all_residues_abs_corr=[]
	#CA_all_residues_abs_reg=[]
	CB_all_residues_abs_corr=[]
	#CB_all_residues_abs_reg=[]
	CO_all_residues_abs_corr=[]
	#CO_all_residues_abs_reg=[]
	HA_all_residues_abs_corr=[]
	#HA_all_residues_abs_reg=[]

	coefflistall=[]

	i_list=[]
	for i in range(-10,11,l_increment):
		i=i/10.0
		i_list=i_list+[i]
	j_list=i_list
	#i_list=[1,0.66,0.33,-0.33,-0.66,-1]
	#smooth_type="no_smooth"
	count=0	
	if lgrid_search_flag==1:
		lCOp_list=lCAp_list=lCBp_list=lHAp_list=lHp_list=lNp_list=lgridsearch_list
	zero_list=[0.000001]	
	if (lfunction_flag==0) or (lfunction_flag==1) or (lfunction_flag==2) or (lfunction_flag==3) or (lfunction_flag==4) or (lfunction_flag==7) or (lfunction_flag==8):
		zero_list=[0]
	if (lfunction_flag==5) or (lfunction_flag==6):
		zero_list=[1]			
		
	if 	lCOp_exclude==1: # If 1, exclude from grid search
		lCOp_list=zero_list
	if lCAp_exclude==1: # If 1, exclude from grid search
		lCAp_list=zero_list
	if lCBp_exclude==1: # If 1, exclude from grid search
		lCBp_list=zero_list
	if lHAp_exclude==1: # If 1, exclude from grid search
		lHAp_list=zero_list
	if lHp_exclude==1: # If 1, exclude from grid search
		lHp_list=zero_list# If 1, exclude from grid search
	if lNp_exclude==1: # If 1, exclude from grid search
		lNp_list=zero_list
	counter=0
	for coefCApos in lCAp_list:
		for coefCAneg in [1]:
			for coefCOpos in lCOp_list:
				for coefCOneg in [1]:
					for coefHApos in lHAp_list:
						for coefHAneg in [1]:
							for coefCBpos in lCBp_list:
								for coefCBneg in [1]:								
									for coefNpos in lNp_list:
										for coefNneg in [1]:								
											for coefHpos in lHp_list:
												for coefHneg in [1]:
													counter=counter+1
	all_the_same_switch=0
	for coefCApos in lCAp_list:																	
	#for coefCApos in [0.5,1]:
		for coefCAneg in [1]:
			for coefCOpos in lCOp_list:
				for coefCOneg in [1]:
					for coefHApos in lHAp_list:
						for coefHAneg in [1]:
							for coefCBpos in lCBp_list:
								for coefCBneg in [1]:								
									for coefNpos in lNp_list:
										for coefNneg in [1]:								
											for coefHpos in lHp_list:
												for coefHneg in [1]:
													count=count+1
													CA_CB_CO_HA_all_residues_abs=[]																
													all_residues_abs=[]
													list_of_coefficients=[]
													if lCAp_exclude!=1:
														list_of_coefficients=list_of_coefficients+[coefCApos]
													if lCOp_exclude!=1:
														list_of_coefficients=list_of_coefficients+[coefCOpos]
													if lHAp_exclude!=1:
														list_of_coefficients=list_of_coefficients+[coefHApos]
													if lCBp_exclude!=1:
														list_of_coefficients=list_of_coefficients+[coefCBpos]	
													if lNp_exclude!=1:
														list_of_coefficients=list_of_coefficients+[coefNpos]
													if lHp_exclude!=1:
														list_of_coefficients=list_of_coefficients+[coefHpos]
													all_zero=1
													skip_switch=0
													all_the_same=1	
													for coef in list_of_coefficients:
														if coef>0.0001:
															all_zero=0
														if abs((coef-(list_of_coefficients[0])))>0.000001:
															all_the_same=0
													#if all_zero==1:
													#	print "ZERO!!!!!!!!!!!!!!!!!!!!!!!!!"		
													if (all_the_same==1) and (all_the_same_switch==1) and (all_zero!=1):
														skip_switch=1
													if (all_the_same==1) and (all_zero!=1):																					
														all_the_same_switch=1
															
													#coeff_list={"CAp":coefCApos,"COp":coefCOpos,"HAp":coefHApos,"CBp":coefCBpos}
													#coeff_list={"CAp":coefCApos,"CAn":coefCAneg,"COp":coefCOpos,"COn":coefCOneg,"HAp":coefHApos,"HAn":coefHAneg,"CBp":coefCBpos,"CBn":coefCBneg,"Np":coefNpos,"Nn":coefNneg,"Hp":coefHpos,"Hn":coefHneg}
													coeff_list={"CAp":coefCApos,"COp":coefCOpos,"HAp":coefHApos,"CBp":coefCBpos,"Np":coefNpos,"Hp":coefHpos}
													#coefflist_rev=[["CAp",-coefCApos],["COp",-coefCOpos],["HAp",-coefHApos],["CBp",-coefCBpos]]
													#coefflist=[["CAp",coefCApos],["COp",coefCOpos],["HAp",coefHApos],["CBp",coefCBpos]]
													#if (coefflist not in coefflistall) and (coefflist_rev not in coefflistall):
													if  skip_switch==1:
														print("SKIP!")
													if (all_zero==0) and (skip_switch==0):
														for residue_number in range(l_firstresidue,(l_lastresidue+1)):
															residue_data_true=[]
															value_true=0
															residue_data_abs=[]
															value_abs=0
															for entry in l_all_atoms_smooth:
													
																resnumber=int(entry[0])										
																true_diff_mean=entry[4]
																abs_diff_mean=entry[5]
																
																atom_type=entry[6]
																if (resnumber==residue_number) and (abs_diff_mean!="NONE"):
																	resname=entry[1]	

																	if (atom_type=="CA"):
																		if pos_neg_value==0:
																			residue_data_abs=residue_data_abs+[[resnumber,resname,abs(abs_diff_mean),coefCApos,atom_type,lCAp_exclude,lCA_Hertz_corr]]
																		else:
																			if true_diff_mean>0:
																				residue_data_abs=residue_data_abs+[[resnumber,resname,true_diff_mean,coef_for_pos_CA*coefCApos,atom_type,lCAp_exclude,lCA_Hertz_corr]]
																			else: 
																				residue_data_abs=residue_data_abs+[[resnumber,resname,true_diff_mean,coef_for_neg_CA*coefCApos,atom_type,lCAp_exclude,lCA_Hertz_corr]]	
								
																	elif (atom_type=="HA"):
																		if pos_neg_value==0:
																			residue_data_abs=residue_data_abs+[[resnumber,resname,abs(abs_diff_mean),coefHApos,atom_type,lHAp_exclude,lH_Hertz_corr]]
																		else: 
																			if true_diff_mean>0:
																				residue_data_abs=residue_data_abs+[[resnumber,resname,true_diff_mean,coef_for_pos_HA*coefHApos,atom_type,lHAp_exclude,lH_Hertz_corr]]
																			else: 
																				residue_data_abs=residue_data_abs+[[resnumber,resname,true_diff_mean,coef_for_neg_HA*coefHApos,atom_type,lHAp_exclude,lH_Hertz_corr]]	
								
											
																		
																	elif (atom_type=="C"):
																		if pos_neg_value==0:
																			residue_data_abs=residue_data_abs+[[resnumber,resname,abs(abs_diff_mean),coefCOpos,atom_type,lCOp_exclude,lCA_Hertz_corr]]											
																		else:
																			
																			if true_diff_mean>0:
																				residue_data_abs=residue_data_abs+[[resnumber,resname,true_diff_mean,coef_for_pos_CO*coefCOpos,atom_type,lCOp_exclude,lCA_Hertz_corr]]
																			else: 
																				residue_data_abs=residue_data_abs+[[resnumber,resname,true_diff_mean,coef_for_neg_CO*coefCOpos,atom_type,lCOp_exclude,lCA_Hertz_corr]]	
								
											
